@dataclass(frozen=True)
class Category:
    id: str
    title: str
    introduction: str
    terms: tuple[Term, ...]


@dataclass(frozen=True)
class Reference:
    title: str
    path: str


@dataclass(frozen=True)
class Model:
    id: str
    title: str
    summary: str
    purpose: str
    working: str
    rationale: str
    limits: tuple[str, ...]
    responsibility: str
    evidence: str
    references: tuple[Reference, ...]
    term_ids: tuple[str, ...]
    aliases: tuple[str, ...] = ()


